import {
  Body,
  Container,
  Head,
  Heading,
  Hr,
  Html,
  Link,
  Preview,
  Section,
  Text,
} from "@react-email/components";
import * as React from "react";

/**
 * Daily DOJ Post Draft — sent to operators each morning shortly after
 * the DOJ scrape completes. The body contains the ready-to-post text
 * generated by `src/lib/daily-post/generate.ts`.
 *
 * Design goals:
 * - Operator can read this on their phone at 7am MT while holding coffee
 * - The post text is presented in a copyable block (plain pre, no rich formatting)
 * - If data is incomplete, warnings are surfaced at the top in amber
 */

interface DailyDojPostDraftEmailProps {
  dateLabel: string;
  templateLabel: string;
  postText: string;
  warnings: string[];
  adminPostUrl: string;
}

export const DailyDojPostDraftEmail = ({
  dateLabel = "Wednesday, April 22, 2026",
  templateLabel = "Midweek insight template",
  postText = "(draft text goes here)",
  warnings = [],
  adminPostUrl = "https://www.radiantclaims.com/admin/daily-post",
}: DailyDojPostDraftEmailProps) => {
  return (
    <Html>
      <Head />
      <Preview>Daily DOJ post draft — {dateLabel}</Preview>
      <Body style={main}>
        <Container style={container}>
          <Section style={header}>
            <Heading style={h1}>Daily DOJ Post Draft</Heading>
            <Text style={subhead}>{dateLabel}</Text>
            <Text style={templateTag}>{templateLabel}</Text>
          </Section>

          {warnings.length > 0 && (
            <Section style={warningBox}>
              <Text style={warningTitle}>⚠ Data warnings</Text>
              {warnings.map((w, i) => (
                <Text key={i} style={warningItem}>
                  • {w}
                </Text>
              ))}
              <Text style={warningNote}>
                Review and replace any [DATA PENDING] markers before posting.
              </Text>
            </Section>
          )}

          <Section style={draftBox}>
            <pre style={pre}>{postText}</pre>
          </Section>

          <Hr style={hr} />

          <Section style={footer}>
            <Text style={footerText}>
              Open the live draft on the admin page to copy with one tap:
            </Text>
            <Link href={adminPostUrl} style={linkStyle}>
              {adminPostUrl}
            </Link>
            <Text style={footerSmall}>
              Reminder: post the eligibility URL as a comment reply, not in the
              post body.
            </Text>
          </Section>
        </Container>
      </Body>
    </Html>
  );
};

export default DailyDojPostDraftEmail;

